// ─── helpers ─────────────────────────────────────────────────────────────────

const SEED_NS = "5eed0000-9a3e-4d7a-8f11-0a1b2c3d4e5f";
/** UUID v5 (SHA-1) of `key` under SEED_NS — stable across runs. */
function sid(key: string): string {
  const ns = Buffer.from(SEED_NS.replace(/-/g, ""), "hex");
  const h = createHash("sha1").update(ns).update(key).digest();
  h[6] = (h[6] & 0x0f) | 0x50; h[8] = (h[8] & 0x3f) | 0x80;
  const x = h.subarray(0, 16).toString("hex");
  return `${x.slice(0, 8)}-${x.slice(8, 12)}-${x.slice(12, 16)}-${x.slice(16, 20)}-${x.slice(20)}`;
}
const NOW = Date.now();
const H = 3600_000, D = 24 * H;
/** ISO timestamp `days` from now (fractions ok), optionally snapped to `hour` local. */
function at(days: number, hour?: number): string {
  const d = new Date(NOW + days * D);
  if (hour !== undefined) d.setHours(hour, 0, 0, 0);
  return d.toISOString();
}
const SEED_DOMAIN = "seed.gameshuffle.dev";
const ADMIN_EMAIL = "brittonlorentzen@gmail.com";
const log = (s: string) => console.log(s);

function genPassword(): string {
  const a = randomBytes(6).toString("base64url").replace(/[-_]/g, "x");
  return `Gs!${a.slice(0, 4)}-${a.slice(4, 8)}7Dev`;
}
function ensureEnv(name: string): string {
  const v = process.env[name];
  if (v) return v;
  const gen = genPassword();
  appendFileSync(".env.local", `\n# generated by scripts/seed-dev.ts\n${name}=${gen}\n`);
  process.env[name] = gen;
  log(`  · generated ${name} → appended to .env.local`);
  return gen;
}

let writes = 0;
async function up<T extends Record<string, unknown>>(table: string, rows: T[], onConflict = "id"): Promise<void> {
  if (rows.length === 0) return;
  if (PLAN) { log(`  plan ${table}: ${rows.length} rows`); return; }
  // PostgREST needs a uniform column set per request (missing keys become NULL,
  // which defeats column defaults) — so group rows by their key signature.
  const groups = new Map<string, T[]>();
  for (const r of rows) { const k = Object.keys(r).sort().join(","); groups.set(k, [...(groups.get(k) ?? []), r]); }
  for (const batch of groups.values()) {
    const { error } = await db.from(table).upsert(batch, { onConflict });
    if (error) throw new Error(`${table}: ${error.message} :: ${JSON.stringify(batch[0]).slice(0, 300)}`);
    writes += batch.length;
  }
}
async function rpc<T = unknown>(fn: string, args: Record<string, unknown>): Promise<T> {
  if (PLAN) return null as T;
  const { data, error } = await db.rpc(fn, args);
  if (error) throw new Error(`${fn}: ${error.message} :: ${JSON.stringify(args).slice(0, 200)}`);
  // economy RPCs report business failures as { ok: false, reason } instead of throwing
  if (data && typeof data === "object" && (data as { ok?: boolean }).ok === false) {
    log(`  ! ${fn} → ${(data as { reason?: string }).reason ?? "not ok"} :: ${JSON.stringify(args).slice(0, 120)}`);
  }
  return data as T;
}
async function patch(table: string, id: string, fields: Record<string, unknown>): Promise<void> {
  if (PLAN) return;
  const { error } = await db.from(table).update(fields).eq("id", id);
  if (error) throw new Error(`${table} patch ${id}: ${error.message}`);
  writes += 1;
}
const share = (key: string) => sid(key).replace(/-/g, "").slice(0, 16);
const pick = <T,>(arr: T[], i: number) => arr[i % arr.length];

